/**
 * Target field options (response time vs resolution time)
 */
export type Target = 'response' | 'resolution';
/**
 * Advanced condition type options
 */
export type AdvancedConditionType = 'none' | 'advanced' | 'advanced_journal' | 'advanced_system' | 'advanced_journal_and_system';
